    day = draw(st.integers(min_value=today, max_value=365))
    start = draw(st.integers(min_value=0, max_value=23))
    end = draw(st.integers(min_value=start + 1, max_value=24))
    capacity = draw(st.integers(min_value=1, max_value=50))
    seats = draw(st.integers(min_value=1, max_value=capacity))
    return today, day, start, end, capacity, seats


@settings(max_examples=50)
@given(data=valid_successful_booking_inputs())
def test_book_success_returns_exact_201_status_and_booking_record(data):
    """A successful book call must return status 201 with the newly assigned booking record."""
    today, day, start, end, capacity, seats = data
    service = Service(FrozenClock(today))
    room = "room"
    create_out = service.create_room(room, capacity)
    assert create_out == (201, {"room": room}), (
        f"input={data!r} output={create_out!r} "
        f"expected={(201, {'room': room})!r}"
    )

    observed = service.book("user", room, day, start, end, seats)
    expected = (201, booking_record(1, room, day, start, end, seats))
    assert observed == expected, (
        f"input={data!r} output={observed!r} expected={expected!r}"
    )
